using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogDataService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogDataService()
    {
        _departments =
        [
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
            new() { Id = 4, Name = "English", Abbreviation = "ENG" },
            new() { Id = 5, Name = "History", Abbreviation = "HIST" },
        ];

        _courses =
        [
            new()
            {
                Id = 1, Code = "CS 101", Title = "Introduction to Computer Science",
                Description = "An introductory course covering fundamental concepts of computer science including algorithms, data structures, and problem-solving techniques. Students will learn to think computationally and write programs in Python.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true,
                Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Associate Professor", Email = "alovelace@university.edu", Bio = "Dr. Lovelace has over 15 years of experience teaching introductory CS courses. Her research focuses on CS education and making computing accessible to all students." }
            },
            new()
            {
                Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms",
                Description = "Advanced study of data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Emphasis on complexity analysis and practical implementation.",
                Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true,
                Instructor = new() { Name = "Dr. Alan Turing", Title = "Professor", Email = "aturing@university.edu", Bio = "Dr. Turing is a renowned researcher in computational theory and algorithm design. He has published over 50 papers and received multiple teaching excellence awards." }
            },
            new()
            {
                Id = 3, Code = "CS 450", Title = "Machine Learning",
                Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation. Students complete a capstone project applying ML to a real-world dataset.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false,
                Instructor = new() { Name = "Dr. Grace Hopper", Title = "Professor", Email = "ghopper@university.edu", Bio = "Dr. Hopper brings extensive industry experience in AI and data science. Before joining academia, she led machine learning teams at several tech companies." }
            },
            new()
            {
                Id = 4, Code = "MATH 201", Title = "Calculus II",
                Description = "Continuation of single-variable calculus covering techniques of integration, applications of integrals, sequences, series, and Taylor polynomials. Prerequisite: MATH 101.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false,
                Instructor = new() { Name = "Dr. Emmy Noether", Title = "Professor", Email = "enoether@university.edu", Bio = "Dr. Noether is an award-winning mathematics educator with a passion for abstract algebra and its connections to calculus. She has authored two widely-used textbooks." }
            },
            new()
            {
                Id = 5, Code = "MATH 310", Title = "Linear Algebra",
                Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and inner product spaces. Emphasis on both theory and computational methods.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true,
                Instructor = new() { Name = "Dr. Emmy Noether", Title = "Professor", Email = "enoether@university.edu", Bio = "Dr. Noether is an award-winning mathematics educator with a passion for abstract algebra and its connections to calculus. She has authored two widely-used textbooks." }
            },
            new()
            {
                Id = 6, Code = "PHYS 101", Title = "General Physics I",
                Description = "Introduction to classical mechanics, thermodynamics, and waves. Includes weekly laboratory sessions where students conduct experiments and analyze data.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM + Lab Thu 2:00–4:50 PM", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false,
                Instructor = new() { Name = "Dr. Richard Feynman", Title = "Distinguished Professor", Email = "rfeynman@university.edu", Bio = "Dr. Feynman is known for his engaging lecture style and ability to explain complex physics concepts intuitively. He has received the university's lifetime teaching award." }
            },
            new()
            {
                Id = 7, Code = "PHYS 320", Title = "Quantum Mechanics",
                Description = "Introduction to quantum theory: wave functions, the Schrödinger equation, quantum states, measurement, and applications to atomic and molecular systems.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true,
                Instructor = new() { Name = "Dr. Richard Feynman", Title = "Distinguished Professor", Email = "rfeynman@university.edu", Bio = "Dr. Feynman is known for his engaging lecture style and ability to explain complex physics concepts intuitively. He has received the university's lifetime teaching award." }
            },
            new()
            {
                Id = 8, Code = "ENG 102", Title = "English Composition",
                Description = "Development of college-level writing skills through essays, research papers, and critical analysis. Focus on argumentation, evidence-based writing, and revision strategies.",
                Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 4, DepartmentName = "English", IsFeatured = false,
                Instructor = new() { Name = "Prof. Maya Angelou", Title = "Senior Lecturer", Email = "mangelou@university.edu", Bio = "Prof. Angelou is a published author and writing instructor with a gift for helping students find their voice. She leads the university's creative writing program." }
            },
            new()
            {
                Id = 9, Code = "ENG 350", Title = "American Literature",
                Description = "Survey of major works and movements in American literature from the colonial period to the present. Explores themes of identity, freedom, and the American experience.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 4, DepartmentName = "English", IsFeatured = false,
                Instructor = new() { Name = "Prof. Maya Angelou", Title = "Senior Lecturer", Email = "mangelou@university.edu", Bio = "Prof. Angelou is a published author and writing instructor with a gift for helping students find their voice. She leads the university's creative writing program." }
            },
            new()
            {
                Id = 10, Code = "HIST 101", Title = "World History to 1500",
                Description = "Survey of world civilizations from prehistory to 1500 CE. Examines the development of cultures, trade networks, political systems, and intellectual traditions across the globe.",
                Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 5, DepartmentName = "History", IsFeatured = false,
