@* Department quick-link list for the homepage *@
<div class="list-group">
    @foreach (var dept in Departments)
    {
        <a href="catalog?departmentId=@dept.Id" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
            <span><strong>@dept.Abbreviation</strong> — @dept.Name</span>
            <span class="badge bg-primary rounded-pill">@dept.CourseCount</span>
        </a>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public required List<Department> Departments { get; set; }
}

@* Search and filter controls for the course catalog *@
<div class="card mb-4">
    <div class="card-body">
        <div class="row g-3 align-items-end">
            <div class="col-md-5">
                <label for="search" class="form-label">Search</label>
                <input id="search" type="text" class="form-control" placeholder="Course name, code, or instructor…"
                       value="@SearchTerm"
                       @oninput="OnSearchInput" />
            </div>
            <div class="col-md-3">
                <label for="department" class="form-label">Department</label>
                <select id="department" class="form-select" value="@DepartmentId" @onchange="OnDepartmentChange">
                    <option value="0">All Departments</option>
                    @foreach (var dept in Departments)
                    {
                        <option value="@dept.Id">@dept.Name</option>
                    }
                </select>
            </div>
            <div class="col-md-2">
                <label for="credits" class="form-label">Credits</label>
                <select id="credits" class="form-select" value="@Credits" @onchange="OnCreditsChange">
                    <option value="0">Any</option>
                    @foreach (var c in AvailableCredits)
                    {
                        <option value="@c">@c</option>
                    }
                </select>
            </div>
            <div class="col-md-2">
                <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public string? SearchTerm { get; set; }
    [Parameter] public int DepartmentId { get; set; }
    [Parameter] public int Credits { get; set; }
    [Parameter, EditorRequired] public required List<Department> Departments { get; set; }
    [Parameter, EditorRequired] public required List<int> AvailableCredits { get; set; }
    [Parameter] public EventCallback<string?> SearchTermChanged { get; set; }
    [Parameter] public EventCallback<int> DepartmentIdChanged { get; set; }
    [Parameter] public EventCallback<int> CreditsChanged { get; set; }

    private async Task OnSearchInput(ChangeEventArgs e)
    {
        SearchTerm = e.Value?.ToString();
        await SearchTermChanged.InvokeAsync(SearchTerm);
    }

    private async Task OnDepartmentChange(ChangeEventArgs e)
    {
        DepartmentId = int.TryParse(e.Value?.ToString(), out var v) ? v : 0;
        await DepartmentIdChanged.InvokeAsync(DepartmentId);
    }

    private async Task OnCreditsChange(ChangeEventArgs e)
    {
        Credits = int.TryParse(e.Value?.ToString(), out var v) ? v : 0;
        await CreditsChanged.InvokeAsync(Credits);
    }

    private async Task ClearFilters()
    {
        SearchTerm = null;
        DepartmentId = 0;
        Credits = 0;
        await SearchTermChanged.InvokeAsync(null);
        await DepartmentIdChanged.InvokeAsync(0);
        await CreditsChanged.InvokeAsync(0);
    }
}

