@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject CatalogDataService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">University Course Catalog</h1>
    <p class="lead text-muted">Browse courses, explore departments, and enroll for the upcoming semester.</p>
    <a href="catalog" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
    <a href="enroll" class="btn btn-outline-success btn-lg">Enroll Now</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in _featuredCourses)
        {
            <div class="col">
                <FeaturedCourseCard Course="course" />
            </div>
        }
    </div>
</section>

<section>
    <h2 class="mb-3">Departments</h2>
    <DepartmentLinkList Departments="_departments" />
</section>

@code {
    private List<Course> _featuredCourses = [];
    private List<Department> _departments = [];

    protected override void OnInitialized()
    {
        _featuredCourses = Catalog.GetFeaturedCourses();
        _departments = Catalog.GetDepartments();
    }
}

arguments.file_text:
@page "/catalog"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject CatalogDataService Catalog

@rendermode InteractiveServer

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<CatalogFilters SearchTerm="@_searchTerm" SearchTermChanged="OnSearchTermChanged"
                DepartmentId="@_departmentId" DepartmentIdChanged="OnDepartmentIdChanged"
                Credits="@_credits" CreditsChanged="OnCreditsChanged"
                Departments="_departments" AvailableCredits="_availableCredits" />

@if (_filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your filters. Try adjusting your search.</div>
}
else
{
    <p class="text-muted mb-3">Showing @_filteredCourses.Count course@(_filteredCourses.Count != 1 ? "s" : "")</p>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in _filteredCourses)
        {
            <div class="col">
                <CourseCard Course="course" />
            </div>
        }
    </div>
}

@code {
    private string? _searchTerm;
    private int _departmentId;
    private int _credits;
    private List<Course> _filteredCourses = [];
    private List<Department> _departments = [];
    private List<int> _availableCredits = [];

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _availableCredits = Catalog.GetDistinctCredits();

        if (DepartmentId.HasValue)
        {
            _departmentId = DepartmentId.Value;
        }

        RefreshCourses();
    }

    private void OnSearchTermChanged(string? term) { _searchTerm = term; RefreshCourses(); }
