toolArgs.new_str:
@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject CatalogDataService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">University Course Catalog</h1>
    <p class="lead text-muted">Browse courses, explore departments, and enroll for the upcoming semester.</p>
    <a href="catalog" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
    <a href="enroll" class="btn btn-outline-success btn-lg">Enroll Now</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in _featuredCourses)
        {
            <div class="col">
                <FeaturedCourseCard Course="course" />
            </div>
        }
    </div>
</section>

<section>
    <h2 class="mb-3">Departments</h2>
    <DepartmentLinkList Departments="_departments" />
</section>

@code {
    private List<Course> _featuredCourses = [];
    private List<Department> _departments = [];

    protected override void OnInitialized()
    {
        _featuredCourses = Catalog.GetFeaturedCourses();
        _departments = Catalog.GetDepartments();
    }
}

toolArgs.file_text:
@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject CatalogDataService Catalog

<PageTitle>@(_course?.Title ?? "Course Not Found")</PageTitle>

@if (_course is null)
{
    <div class="alert alert-warning">Course not found. <a href="catalog">Back to catalog</a></div>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="catalog">Catalog</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@_course.Code — @_course.Title</h1>
            <span class="badge bg-secondary mb-3">@_course.DepartmentName</span>

            <h4 class="mt-4">Description</h4>
            <p>@_course.Description</p>

            <h4>Schedule</h4>
            <p>@_course.Schedule</p>

            <h4>Credits</h4>
            <p><span class="badge bg-info text-dark fs-6">@_course.Credits</span></p>

            <a href="enroll?courseId=@_course.Id" class="btn btn-success mt-3">Request Enrollment</a>
        </div>
        <div class="col-lg-4">
            <InstructorBio Instructor="_course.Instructor" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? _course;

    protected override void OnInitialized()
    {
        _course = Catalog.GetCourseById(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@inject CatalogDataService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@_model.Name</strong>. Your enrollment request for
            <strong>@_courses.FirstOrDefault(c => c.Id == _model.CourseId)?.Title</strong>
            has been received. You will receive a confirmation at your university email.</p>
        <hr />
        <a href="enroll" class="btn btn-outline-success">Submit Another</a>
        <a href="catalog" class="btn btn-outline-primary ms-2">Back to Catalog</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-6">
            <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
                <DataAnnotationsValidator />
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="name" class="form-label">Full Name</label>
                    <InputText id="name" class="form-control" @bind-Value="_model.Name" />
                    <ValidationMessage For="() => _model.Name" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" placeholder="e.g., CS123456" @bind-Value="_model.StudentId" />
                    <ValidationMessage For="() => _model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="course" class="form-label">Course</label>
                    <InputSelect id="course" class="form-select" @bind-Value="_model.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in _courses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => _model.CourseId" />
                </div>

                <button type="submit" class="btn btn-success">Submit Request</button>
                <a href="catalog" class="btn btn-outline-secondary ms-2">Cancel</a>
            </EditForm>
        </div>
        <div class="col-lg-6">
            <div class="card bg-light">
                <div class="card-body">
                    <h5 class="card-title">Enrollment Information</h5>
                    <ul class="mb-0">
                        <li>Enrollment requests are reviewed within 2 business days.</li>
                        <li>You will receive confirmation at your university email address.</li>
                        <li>Prerequisites are verified automatically during processing.</li>
                        <li>Contact the Registrar's Office for questions.</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> _courses = [];
    private bool _submitted;

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        if (CourseId.HasValue && _model.CourseId == 0)
        {
            _model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        _submitted = true;
    }
}

